<div class='page-header mb-3'><h2 class='page-title'><?=e($title)?></h2></div><form method='post' action='<?=e($action)?>'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><div class='card mb-3'><div class='card-body'><div class='row'><div class='col-md-3'><label class='form-label'>التاريخ</label><input class='form-control' type='date' name='journal_date' value='<?=e($journal['journal_date']??date('Y-m-d'))?>' required></div><div class='col-md-6'><label class='form-label'>الوصف</label><input class='form-control' name='description' value='<?=e($journal['description']??'')?>' required></div><div class='col-md-3'><label class='form-label'>المرجع</label><input class='form-control' name='reference' value='<?=e($journal['reference']??'')?>'></div></div></div></div><div class='card'><div class='table-responsive'><table class='table' id='journal-lines'><thead><tr><th>الحساب والوصف</th><th>مدين</th><th>دائن</th><th>الأبعاد</th></tr></thead><tbody><?php foreach($rows as$i=>$l):?><tr><td><select class='form-select mb-1' name='lines[<?=$i?>][account_id]' required><option value=''>اختر الحساب</option><?php foreach($accounts as$a):?><option value='<?=e($a['id'])?>' <?=($l['account_id']??null)==$a['id']?'selected':''?>><?=e($a['account_code'].' - '.$a['name_ar'])?></option><?php endforeach;?></select><input class='form-control' name='lines[<?=$i?>][description]' value='<?=e($l['description']??'')?>' placeholder='وصف السطر' required></td><td><input class='form-control' name='lines[<?=$i?>][debit]' value='<?=e($l['debit']??'0.00')?>' inputmode='decimal'></td><td><input class='form-control' name='lines[<?=$i?>][credit]' value='<?=e($l['credit']??'0.00')?>' inputmode='decimal'></td><td><select class='form-select mb-1' name='lines[<?=$i?>][project_id]'><option value=''>مشروع</option><?php foreach($projects as$x):?><option value='<?=e($x['id'])?>' <?=($l['project_id']??null)==$x['id']?'selected':''?>><?=e($x['project_code'])?></option><?php endforeach;?></select><select class='form-select' name='lines[<?=$i?>][employee_id]'><option value=''>موظف</option><?php foreach($employees as$x):?><option value='<?=e($x['id'])?>' <?=($l['employee_id']??null)==$x['id']?'selected':''?>><?=e($x['employee_code'].' - '.$x['name'])?></option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div><div class='card-footer'><button class='btn btn-primary'>حفظ المسودة</button></div></div></form>
